442|// One failed upload: coded errors map to the next step, never a dead end.
443|function FailedView({
444|  status,
445|  idleKey,
446|  onRetryKey,
447|  onRetryToken,
448|  onRetry,
449|  onReset,
450|}: {
451|  status: Extract<Status, { step: "failed" }>;
452|  idleKey: string;
453|  onRetryKey: (key: string) => void;
454|  onRetryToken: (token: string) => void;
455|  onRetry: () => void;
456|  onReset: () => void;
457|}) {
458|  const code = status.code;
459|  if (code === "too_long" || code === "daily_books_reached" || code === "daily_budget_reached") {
460|    return (
461|      <div>
462|        <ByokStep
463|          metaOnly
464|          note={UPLOAD_MESSAGES[code]}
465|          initialKey={idleKey}
466|          actionLabel="Bring your own key!"
467|          onSubmit={onRetryKey}
468|        />
469|        <div className="ob-actions">
470|          <button className="ob-quiet" type="button" onClick={onReset}>
471|            Choose another book
472|          </button>
473|        </div>
474|      </div>
475|    );
476|  }
477|  if (code === "human_required") {
478|    return (
479|      <div>
480|        <p className="ob-note">{UPLOAD_MESSAGES.human_required} Complete the check and we&apos;ll pick up where we left off.</p>
481|        <TurnstileWidget onToken={onRetryToken} />
482|        <div className="ob-actions">
483|          <button className="ob-action" type="button" onClick={onRetry}>
484|            Try again
