130|export function Reader({
131|  bookId,
132|  scenes,
133|  chapters,
134|  bookTitle,
135|  bookAuthor,
136|  narration,
137|  children,
138|}: {
139|  bookId: string;
140|  scenes: SlimScene[];
141|  chapters: ChapterJump[];
142|  bookTitle: string;
143|  bookAuthor: string;
144|  narration: NarrationChapterEntry[];
145|  children: React.ReactNode;
146|}) {
147|  const routeParams = useParams();
148|  const param = routeParams?.sceneId;
149|  // The reading column publishes the scene in view through replaceState
150|  // and the live store; App Router params may not follow replaceState,
151|  // so the store wins and the route id is only the first-load fallback.
152|  const routeSceneId = useCurrentSceneId() ?? (typeof param === "string" ? param : null);
153|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
154|  const [view, setView] = useState<SessionView | null>(null);
155|  const [musicFailed, setMusicFailed] = useState(false);
156|  // Volume, mute, style, and Chopin mode persist in one prefs object;
157|  // the player stays a controlled view over them. State starts at the server
158|  // defaults so hydration matches, then a mount effect applies stored
159|  // prefs (parsed once) to volume, muted, and style via the prefs store.
160|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
161|  const [muted, setMuted] = useState(false);
162|  const [theme, setTheme] = useState<"light" | "dark">("light");
163|  const [devOpen, setDevOpen] = useState(false);
164|  const [sceneAttr, setSceneAttr] = useState<SceneAttr | null>(null);
165|  const prefsStoreRef = useRef(createMusicPrefsStore());
166|  // Ref mirrors so send and persist handlers always read fresh values.
167|  const volumeRef = useRef(volume);
168|  // eslint-disable-next-line react-hooks/refs -- latest-value mirror so music handlers read fresh state
169|  volumeRef.current = volume;
170|  const mutedRef = useRef(muted);
171|  // eslint-disable-next-line react-hooks/refs -- latest-value mirror so music handlers read fresh state
172|  mutedRef.current = muted;
173|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
174|  const byIdRef = useRef(byId);
175|  // eslint-disable-next-line react-hooks/refs -- latest-value mirror so music handlers read fresh state
176|  byIdRef.current = byId;
177|  const manifestRef = useRef(manifest);
178|  // eslint-disable-next-line react-hooks/refs -- latest-value mirror so music handlers read fresh state
179|  manifestRef.current = manifest;
180|  const routeRef = useRef(routeSceneId);
181|  // eslint-disable-next-line react-hooks/refs -- latest-value mirror so music handlers read fresh state
182|  routeRef.current = routeSceneId;
183|  const sessionRef = useRef<MusicSession | null>(null);
184|  const observedRef = useRef<string | null>(null);
185|
186|  // The one bridge into the session: builds the context (clock, rng,
187|  // scene signals) and mirrors the view and a style change to state.
188|  const send = useCallback((intent: MusicIntent) => {
189|    const session = sessionRef.current;
190|    const fetched = manifestRef.current;
191|    if (!session || !fetched) return;
192|    const prevView = session.view;
193|    const next = dispatch(session, intent, {
194|      manifest: fetched,
195|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
196|      routeSceneId: routeRef.current,
197|      nowSec: Date.now() / 1000,
198|      rng: Math.random,
199|      excludeTrackId: prefsStoreRef.current.load()?.lastTrackId ?? null,
200|    });
201|    sessionRef.current = next;
202|    if (next.view !== prevView) setView(next.view);
203|    // Remember the last track that started playing so the next session
204|    // opens on something else. Merge-updates never clobber other fields.
205|    if (next.view.currentId !== prevView.currentId && next.view.currentId !== null) {
206|      prefsStoreRef.current.update({ lastTrackId: next.view.currentId });
207|    }
208|    if (next.selection !== session.selection || next.view.playlistOn !== prevView.playlistOn) {
209|      prefsStoreRef.current.update({
210|        style: next.selection.style,
211|        playlist: next.view.playlistOn,
212|      });
213|    }
214|  }, []);
215|
216|  // Stored prefs load once here, after the server-matching first render.
217|  // Saves happen only on user actions below, so the defaults above never
218|  // overwrite storage before this runs. The fetch below resolves later and
219|  // reads the style through the store.
220|  useEffect(() => {
221|    const prefs = prefsStoreRef.current.load();
222|    if (prefs !== null) {
223|      if (prefs.volume !== null) setVolume(prefs.volume);
224|      setMuted(prefs.muted);
225|    }
226|    try {
227|      setTheme(initialTheme(window.localStorage.getItem(THEME_KEY)));
228|    } catch {
229|      // The inline script already set a theme; keep the default.
230|    }
231|    if (new URLSearchParams(window.location.search).has("dev")) setDevOpen(true);
232|  }, []);
233|
234|  useEffect(() => {
235|    let cancelled = false;
236|    fetch("/music/manifest.json", { signal: AbortSignal.timeout(15_000) })
237|      .then((res) => {
238|        if (!res.ok) throw new Error(`manifest ${res.status}`);
239|        return res.json();
240|      })
241|      .then((json: unknown) => {
242|        if (cancelled) return;
243|        const parsed = choosePlayableSources(parseManifest(json), canPlayAudio);
244|        setManifest(parsed);
245|        const session = startSession(parsed, prefsStoreRef.current.load(), Math.random);
246|        sessionRef.current = session;
247|        setView(session.view);
248|      })
249|      .catch(() => {
250|        if (!cancelled) setMusicFailed(true);
251|      });
252|    return () => {
253|      cancelled = true;
254|    };
255|  }, []);
256|
257|  // Scene entry: exactly one sceneEntered per scene id, once the manifest
258|  // lands. The first scene cues at once, so it plays on the first press.
259|  useEffect(() => {
260|    const gate = nextSceneEntry({
261|      observedId: observedRef.current,
262|      routeId: routeSceneId,
263|      manifestReady: manifest !== null,
264|    });
265|    observedRef.current = gate.nextObservedId;
266|    if (gate.shouldObserve && routeSceneId) send({ type: "sceneEntered", sceneId: routeSceneId });
267|  }, [routeSceneId, manifest, send]);
268|
269|  useEffect(() => {
270|    // Settle an expired entry dwell, or re-check the scene after a hold.
271|    const timer = window.setInterval(() => {
272|      send({ type: "tick" });
273|    }, 1000);
274|    return () => window.clearInterval(timer);
275|  }, [send]);
276|
277|  // Developer view slice: fetched on demand while the panel is open,
278|  // so the page never ships all scenes' attrs. Stale requests abort on
279|  // scene change; any failure hides the section.
280|  useEffect(() => {
281|    if (!devOpen || !routeSceneId) {
282|      // eslint-disable-next-line react-hooks/set-state-in-effect -- dev panel clears the scene slice when closed
283|      setSceneAttr(null);
284|      return;
285|    }
286|    const controller = new AbortController();
287|    setSceneAttr(null);
288|    fetch(
289|      `/api/scene-attrs?bookId=${encodeURIComponent(bookId)}&sceneId=${encodeURIComponent(routeSceneId)}`,
290|      { signal: controller.signal },
291|    )
292|      .then((res) => {
293|        if (!res.ok) throw new Error(`scene attrs ${res.status}`);
294|        return res.json() as Promise<unknown>;
295|      })
296|      .then((json) => {
297|        if (isSceneAttr(json)) setSceneAttr(json);
298|      })
299|      .catch(() => {
300|        // The panel hides the section on any failure.
301|      });
302|    return () => controller.abort();
303|  }, [devOpen, routeSceneId, bookId]);
304|
305|  // Developer view: Shift+D outside inputs, Escape closes.
306|  useEffect(() => {
307|    const onKey = (event: KeyboardEvent) => {
308|      const target = event.target as HTMLElement | null;
309|      const typing =
310|        !!target &&
311|        (target.tagName === "INPUT" ||
312|          target.tagName === "SELECT" ||
313|          target.tagName === "TEXTAREA" ||
314|          target.isContentEditable);
315|      if (event.key === "Escape") {
316|        setDevOpen(false);
317|        return;
318|      }
319|      if (typing) return;
320|      if (event.shiftKey && (event.key === "D" || event.key === "d")) {
321|        event.preventDefault();
322|        setDevOpen((open) => !open);
323|      }
324|    };
325|    window.addEventListener("keydown", onKey);
326|    return () => window.removeEventListener("keydown", onKey);
327|  }, []);
328|
329|  function skip() {
330|    send({ type: "skip" });
331|  }
332|
333|  // Previous: back to the last played track, held like a Next. With no
334|  // history the current track restarts from zero through the replay path,
335|  // including in playlist mode.
336|  function goPrev() {
337|    send({ type: "previous" });
338|  }
339|
340|  function advanceMode(to?: MusicModeId) {
341|    send({ type: "modeAdvanced", to });
342|  }
343|
344|  function changeVolume(next: number) {
345|    setVolume(next);
346|    volumeRef.current = next;
347|    prefsStoreRef.current.update({ volume: next });
348|  }
349|
350|  function changeMuted(next: boolean) {
351|    setMuted(next);
352|    mutedRef.current = next;
353|    prefsStoreRef.current.update({ muted: next });
354|  }
355|
356|  function ended(trackId: string) {
357|    send({ type: "trackEnded", trackId });
358|  }
359|
360|  function toggleTheme() {
361|    setTheme((current) => {
362|      const next = current === "dark" ? "light" : "dark";
363|      document.documentElement.setAttribute("data-theme", next);
364|      try {
365|        window.localStorage.setItem(THEME_KEY, next);
366|      } catch {
367|        // The attribute already applies for the session.
368|      }
369|      return next;
370|    });
371|  }
372|
373|  function jumpChapter(ch: number) {
374|    const found = chapters.find((c) => c.ch === ch);
375|    if (found) requestGotoScene(found.firstSceneId);
376|  }
377|
378|  const currentId = view?.currentId ?? null;
379|  const track = manifest?.tracks.find((t) => t.id === currentId) ?? null;
380|  const empty = manifest !== null && manifest.tracks.length === 0;
381|  // Ordered music modes for the control: styles with tracks, then Chopin.
382|  const modes = manifest ? musicModes(manifest) : [];
383|  const modeCurrent = view ? currentMode(view) : null;
384|  const playlistOn = view?.playlistOn ?? false;
385|  // Previous restarts the track with no history (including the current
386|  // playlist piece), so it stays on whenever a track is cued.
387|  const canPrev = view?.canPrev ?? false;
388|  const canSkip = view?.canSkip ?? false;
389|
390|  const bookIndex = routeSceneId ? scenes.findIndex((s) => s.id === routeSceneId) : -1;
391|  const current = routeSceneId ? byId.get(routeSceneId) ?? null : null;
392|  // Reader chat position: the scene in view, or the first scene on load.
393|  const chatScene = (routeSceneId ? scenes.find((s) => s.id === routeSceneId) : null) ?? scenes[0];
394|  const chatChapter = chapters.find((c) => c.ch === chatScene?.ch) ?? chapters[0];
395|  const devBars = current
396|    ? EMOTIONS.map((id) => ({ label: DEV_LABELS[id], value: current.vector[id] ?? 0 }))
397|    : [];
398|
399|
400|  // Chat runs on our key for shelf books only, so uploads read without it.
401|  const chatOn = !isUploadId(bookId);
402|  return (
403|    <NarrationProvider entries={narration} scenes={scenes}>
404|      <div className="folio">
405|        <a href="#story" className="skip-link">
406|          Skip to the story
407|        </a>
408|        <TopLine
409|          bookTitle={bookTitle}
410|          author={bookAuthor}
411|          ch={routeSceneId ? (scenes[bookIndex]?.ch ?? chapters[0]?.ch ?? 1) : 1}
412|          chaptersTotal={chapters.length}
413|          chapters={chapters}
414|          onJumpChapter={jumpChapter}
415|          theme={theme}
416|          onToggleTheme={toggleTheme}
417|        />
418|        {children}
419|        <BandPlay
420|          narrationOn={hasNarration(narration)}
421|          musicFailed={musicFailed}
422|          empty={empty}
423|          track={track}
424|          replayNonce={view?.replayNonce ?? 0}
425|          fadeSec={view?.fadeSec ?? 0}
426|          canPrev={canPrev}
427|          onPrev={goPrev}
428|          canSkip={canSkip}
429|          onSkip={skip}
430|          volume={volume}
431|          muted={muted}
432|          onVolumeChange={changeVolume}
433|          onMutedChange={changeMuted}
434|          modes={modes}
435|          current={modeCurrent}
436|          onAdvance={advanceMode}
437|          onEnded={ended}
438|          playlistOn={playlistOn}
439|        />
440|      {chatOn && chatScene && chatChapter && (
441|        <ReaderChat
442|          bookId={bookId}
443|          upToN={chatScene.endN}
444|          chapter={chatChapter.ch}
445|          chapterTitle={chatChapter.title}
446|        />
447|      )}
448|      <DevPanel
449|        open={devOpen}
450|        onClose={() => setDevOpen(false)}
451|        sceneLabel={bookIndex >= 0 ? `scene ${bookIndex + 1} of ${scenes.length}` : "no scene"}
452|        bars={devBars}
453|        intensity={current?.intensity ?? null}
454|        tempo={current?.tempo ?? null}
455|        trackTitle={track?.title ?? "No track cued"}
456|        sceneAttr={sceneAttr}
457|      />
458|      </div>
459|    </NarrationProvider>
460|  );
461|}
