1|import "server-only";
2|import {
3|  BYOK_HEADER,
4|  CHAT_BYOK_DAILY_LIMIT,
5|  CHAT_DAILY_LIMIT,
6|  CHAT_MAX_ANSWER_CHARS,
7|  CHAT_MAX_BODY_BYTES,
8|  CHAT_MESSAGES,
9|  HTTP_STATUS,
10|  bookTextUpTo,
11|  buildChatSystemPrompt,
12|  chatQuotaKeys,
13|  encodeSse,
14|  estimateCostMicro,
15|  parseChatRequest,
16|  usageCostMicro,
17|} from "@/core/chat";
18|import type { ChatErrorBody, ChatErrorCode, ChatRequest } from "@/core/chat";
19|import type { KV } from "@/core/types";
20|import { isKnownBookId, loadBookData } from "@/server/books";
21|import {
22|  issueAnonId,
23|  parseAnonCookie,
24|  serializeAnonCookie,
25|  verifyAnonCookie,
26|} from "@/server/guard/anon";
27|import { readBodyCapped } from "@/server/guard/body";
28|import { checkHuman } from "@/server/guard/human";
29|import { createRestKV } from "@/server/guard/kv";
30|import { CHAT_QUOTA_TTL_SEC, refundDualQuota, takeDualQuota } from "@/server/guard/quota";
31|import { clientIp, hashIp, ipBucket, rejectsCrossSite, utcDay } from "@/server/guard/request";
32|import { reserveSpend } from "@/server/guard/spend";
33|import type { SpendReservation } from "@/server/guard/spend";
34|import { readChatEnv } from "./env";
35|import type { ChatEnv } from "./env";
36|import { createChatStreamer } from "./stream";
37|import type { ChatStreamChunk, ChatStreamer, UpstreamMessage } from "./stream";
38|
39|export interface ChatHandlerDeps {
40|  env?: ChatEnv;
41|  kv?: KV;
42|  createStreamer?: (args: { apiKey: string; fetchFn: typeof fetch }) => ChatStreamer;
43|  fetchFn?: typeof fetch;
44|  now?: Date;
45|}
46|
47|// Expected failures (bad input, over limit, missing env, spent budget)
48|// warn; only a truly unexpected crash (upstream or ours) errors. Names
49|// only, never request text, keys, or error values.
50|function fail(
51|  code: ChatErrorCode,
52|  ch: number | "?",
53|  cookies: string[],
54|  unexpected = false,
55|  book: string | "?" = "?",
56|): Response {
57|  if (unexpected) console.error(`chat ${code} book=${book} ch=${ch}`);
58|  else console.warn(`chat ${code} book=${book} ch=${ch}`);
59|  const headers = new Headers();
60|  for (const cookie of cookies) headers.append("Set-Cookie", cookie);
61|  return Response.json(
62|    { status: "error", code, message: CHAT_MESSAGES[code] } satisfies ChatErrorBody,
63|    { status: HTTP_STATUS[code], headers },
64|  );
65|}
66|
67|function isAsciiPrintable(text: string): boolean {
68|  return /^[\x20-\x7E]+$/.test(text);
69|}
70|
71|// Order: body cap and shape, env, Turnstile, anonymous cookie, per-person
72|// quota, global caps, upstream. A question that produced no token refunds
73|// its quota and spend reserves; mid-stream failures do not.
74|export async function handleChatPost(req: Request, deps: ChatHandlerDeps = {}): Promise<Response> {
75|  const cookies: string[] = [];
76|
77|  if (rejectsCrossSite(req.headers, req.url)) return fail("bad_request", "?", cookies);
78|
79|  const capped = await readBodyCapped(req, CHAT_MAX_BODY_BYTES);
80|  if (!capped.ok) return fail(capped.reason === "too_large" ? "too_large" : "bad_request", "?", cookies);
81|
82|  let body: ChatRequest;
83|  try {
84|    body = parseChatRequest(JSON.parse(capped.text));
85|  } catch {
86|    return fail("bad_request", "?", cookies);
87|  }
88|  if (!isKnownBookId(body.bookId)) return fail("bad_request", "?", cookies, false, body.bookId);
89|
90|  let env = deps.env;
91|  if (!env) {
92|    try {
93|      env = readChatEnv();
94|    } catch (e) {
95|      const message = e instanceof Error ? e.message : "";
96|      const prefix = "missing chat env:";
97|      console.warn(`chat env missing: ${message.startsWith(prefix) ? message.slice(prefix.length).trim() : ""}`);
98|      return fail("unavailable", "?", cookies, false, body.bookId);
99|    }
100|  }
101|
102|  const fetchFn = deps.fetchFn ?? fetch;
103|  const ip = clientIp(req.headers);
104|  const human = await checkHuman({
105|    cookieHeader: req.headers.get("cookie"),
106|    token: body.turnstileToken,
107|    ip,
108|    turnstileSecret: env.turnstileSecret,
109|    turnstileSiteKey: env.turnstileSiteKey,
110|    sessionSecret: env.sessionSecret,
111|    fetchFn,
112|  });
113|  if (!human.ok) return fail("human", "?", cookies, false, body.bookId);
114|  if (human.setCookie) cookies.push(human.setCookie);
115|
116|  let anonId = verifyAnonCookie(parseAnonCookie(req.headers.get("cookie")), env.sessionSecret);
117|  if (!anonId) {
118|    const issued = issueAnonId(env.sessionSecret);
119|    anonId = issued.id;
120|    cookies.push(serializeAnonCookie(issued.value));
121|  }
122|
123|  const rawByok = req.headers.get(BYOK_HEADER);
124|  let byokKey: string | null = null;
125|  if (rawByok !== null) {
126|    const trimmed = rawByok.trim();
127|    if (trimmed.length < 8 || trimmed.length > 400 || !isAsciiPrintable(trimmed)) {
128|      return fail("bad_request", "?", cookies, false, body.bookId);
129|    }
130|    byokKey = trimmed;
131|  }
132|  const byok = byokKey !== null;
133|  const limit = byok ? CHAT_BYOK_DAILY_LIMIT : CHAT_DAILY_LIMIT;
134|
135|  const kv = deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken);
136|  const day = utcDay(deps.now ?? new Date());
137|  const keys = chatQuotaKeys({
138|    day,
139|    ipHash: hashIp(ipBucket(ip, anonId), env.ipSalt),
140|    anonId,
141|    byok,
142|  });
143|
144|  let quotaTaken = false;
145|  let reservation: SpendReservation | null = null;
146|  // Each reserve is refunded at most once: flags clear only after the
147|  // write lands, like the images orchestrate path.
148|  const refundQuotaOnce = async (): Promise<void> => {
149|    if (quotaTaken) {
150|      await refundDualQuota(kv, keys);
151|      quotaTaken = false;
152|    }
153|  };
154|  const releaseSpendOnce = async (): Promise<void> => {
155|    await reservation?.release();
156|    reservation = null;
157|  };
158|  const refundAll = async (): Promise<void> => {
159|    await releaseSpendOnce();
160|    await refundQuotaOnce();
161|  };
162|  try {
163|    const taken = await takeDualQuota(kv, keys, { limit, ttlSec: CHAT_QUOTA_TTL_SEC });
164|    if (!taken.ok) return fail("quota", "?", cookies, false, body.bookId);
165|    quotaTaken = true;
166|    const remaining = limit - Math.max(taken.ipCount, taken.anonCount);
