44|  peterpan: () =>
45|    pair(
46|      import("../data/books/peterpan/book.json"),
47|      import("../data/books/peterpan/analysis.json"),
48|    ),
49|  pride: () =>
50|    pair(import("../data/books/pride/book.json"), import("../data/books/pride/analysis.json")),
51|  sherlock: () =>
52|    pair(
53|      import("../data/books/sherlock/book.json"),
54|      import("../data/books/sherlock/analysis.json"),
55|    ),
56|  treasure: () =>
57|    pair(
58|      import("../data/books/treasure/book.json"),
59|      import("../data/books/treasure/analysis.json"),
60|    ),
61|};
