67|const readyIds = new Set(shelfReadyIds());
68|
69|// Known plus listed on the shelf with status ready. The shelf manifest
70|// is the owner's switch: data alone does not publish a book.
71|export function isReadyBookId(id: unknown): boolean {
72|  return isKnownBookId(id) && readyIds.has(id);
73|}
74|
75|export function readyBookIds(): string[] {
76|  return shelfReadyIds().filter(isKnownBookId);
77|}
78|
79|// Parsed once per book per process; import failures are deterministic
80|// (a missing chunk never heals), so failed loads stay failed.
81|const cache = new Map<string, Promise<BookPayload>>();
82|
83|function readPayload(id: string): Promise<BookPayload> {
84|  const hit = cache.get(id);
85|  if (hit) return hit;
86|  const load = LOADERS[id];
