93|// Processed data for any known id. Chat uses this: a question about a
94|// processed book is answerable whether the shelf lists it or not.
95|// Unknown ids throw notFound() synchronously, before any work starts.
96|// Uploads never load here, so chat stays shelf-only; pictures load
97|// uploads through loadBook below instead.
98|export function loadBookData(bookId: string): Promise<BookPayload> {
99|  if (!isKnownBookId(bookId)) notFound();
100|  return readPayload(bookId);
101|}
102|
103|// Shelf books plus finished uploads. Missing, unfinished, or expired
104|// uploads 404 like unknown ids. Uploads bypass the module cache: they
105|// expire after 30 days, so a forever entry would serve a dead book.
106|export function loadBook(bookId: string): Promise<BookPayload> {
107|  if (isUploadId(bookId)) {
108|    return loadUploadedBook(bookId).then((payload) => {
109|      if (!payload) notFound();
110|      return payload;
111|    });
112|  }
113|  if (!isReadyBookId(bookId)) notFound();
114|  return readPayload(bookId);
