269|            // No JSON error body: keep the generic code.
270|          }
271|          throw { code };
272|        }
273|        let streamed = false;
274|        let finished = false;
275|        const role: ChatRole = "assistant";
276|        await runStream(res, ctrl.signal, (event, data) => {
277|          if (event === "delta") {
278|            const text = (safeJson(data) as { text?: unknown } | null)?.text;
279|            if (typeof text !== "string" || text === "") return;
280|            streamed = true;
281|            setStatus("streaming");
282|            const next = [...msgsRef.current];
283|            const last = next[next.length - 1];
284|            if (last && last.role === role) {
285|              next[next.length - 1] = { role, content: last.content + text };
286|            } else {
287|              next.push({ role, content: text });
288|            }
289|            msgsRef.current = next;
290|            setMessages(next);
291|          } else if (event === "done") {
292|            const left = (safeJson(data) as { remaining?: unknown } | null)?.remaining;
293|            if (typeof left === "number") setRemaining(left);
294|            finished = true;
295|            setStatus("idle");
296|            abortRef.current = null;
297|          } else if (event === "error") {
298|            throw { code: errorCodeOf(safeJson(data)) };
299|          }
300|        });
301|        // A cut stream (server kill, dropped line) ends without done: show
302|        // the retry state instead of streaming forever.
303|        if ((!streamed || !finished) && !ctrl.signal.aborted) throw { code: "unavailable" };
304|      } catch (err) {
305|        // Stop stays silent; anything else (first-byte or idle timeout,
306|        // network, server error) lands here unaborted and shows its state.
307|        if (ctrl.signal.aborted) return;
308|        throw err;
309|      }
310|    },
311|    [],
312|  );
313|
314|  const submit = useCallback(
315|    (history: ChatMessage[], key: string | null, token: string | null) => {
316|      void sendHistory(history, key, token).catch((err: unknown) => {
317|        fail(typeof err === "string" ? err : errorCodeOf(err));
318|      });
319|    },
320|    [sendHistory, fail],
321|  );
322|
323|  const send = useCallback(
324|    (question: string) => {
325|      const o = optsRef.current;
326|      const q = question.trim().slice(0, CHAT_MAX_QUESTION_CHARS);
327|      if (q === "" || abortRef.current) return;
328|      const next: ChatMessage[] = [...msgsRef.current, { role: "user", content: q }];
329|      msgsRef.current = next;
330|      setMessages(next);
331|      submit(next.slice(-(CHAT_MAX_MESSAGES - 1)), o.byokKey, o.turnstileToken);
332|    },
333|    [submit],
334|  );
335|
336|  // "Try again" and post-key/post-check retries resend the same question,
337|  // kept in place. Overrides cover keys and tokens set in the same tick.
338|  const retry = useCallback(
339|    (overrides?: { key?: string | null; token?: string | null }) => {
340|      const o = optsRef.current;
341|      const current = msgsRef.current;
342|      for (let i = current.length - 1; i >= 0; i--) {
343|        if (current[i]?.role === "user") {
344|          const trimmed = current.slice(0, i + 1);
345|          msgsRef.current = trimmed;
346|          setMessages(trimmed);
347|          submit(
348|            trimmed.slice(-(CHAT_MAX_MESSAGES - 1)),
349|            overrides && "key" in overrides ? (overrides.key ?? null) : o.byokKey,
350|            overrides && "token" in overrides ? (overrides.token ?? null) : o.turnstileToken,
351|          );
352|          return;
353|        }
354|      }
355|    },
356|    [submit],
357|  );
358|
359|  return {
360|    messages,
361|    status,
362|    remaining,
363|    spoilers,
364|    setSpoilers,
365|    byok,
366|    needHuman,
367|    setNeedHuman,
368|    send,
369|    retry,
370|    stop,
371|    startOver,
372|    busy: status === "loading" || status === "streaming",
373|  };
374|}

