33|function readStored(key: string): ChatSnapshot | null {
34|  try {
35|    const raw = window.sessionStorage.getItem(key);
36|    if (!raw) return null;
37|    const parsed = JSON.parse(raw) as Partial<ChatSnapshot>;
38|    if (!Array.isArray(parsed.messages)) return null;
39|    const messages = parsed.messages.filter(
40|      (m): m is ChatMessage =>
41|        !!m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string",
42|    );
43|    return {
44|      messages,
45|      remaining: typeof parsed.remaining === "number" ? parsed.remaining : null,
46|      spoilers: parsed.spoilers === true,
47|    };
48|  } catch {
49|    return null; // Corrupt entry: start fresh, never throw.
