69|// First byte and idle budgets: the server answers with headers quickly
70|// and streams at once, so a quiet line means it is stuck, not thinking.
71|// Never a total budget: a long healthy answer must never trip it.
72|export const CHAT_FIRST_BYTE_MS = 30_000;
73|export const CHAT_IDLE_MS = 30_000;
74|
75|const IDLE_TIMEOUT = Symbol("chat-idle-timeout");
76|
77|// One read with an idle budget. Handlers stay attached, so a won read
78|// settling late after the timeout never rejects unhandled.
79|function readWithIdle(
80|  reader: ReadableStreamDefaultReader<Uint8Array>,
81|  ms: number,
82|): Promise<ReadableStreamReadResult<Uint8Array>> {
83|  return new Promise((resolve, reject) => {
84|    const timer = setTimeout(() => reject(IDLE_TIMEOUT), ms);
85|    reader.read().then(
86|      (value) => {
87|        clearTimeout(timer);
88|        resolve(value);
89|      },
90|      (err: unknown) => {
91|        clearTimeout(timer);
92|        reject(err);
93|      },
94|    );
95|  });
