151|export function useChat(opts: UseChatOptions) {
152|  const [messages, setMessages] = useState<ChatMessage[]>([]);
153|  const [status, setStatus] = useState<ChatStatus>("idle");
154|  const [remaining, setRemaining] = useState<number | null>(null);
155|  const [spoilers, setSpoilers] = useState(false);
156|  const [byok, setByok] = useState<ByokReason | null>(null);
157|  const [needHuman, setNeedHuman] = useState(false);
158|
159|  const optsRef = useRef(opts);
