161|  optsRef.current = opts;
162|  const spoilersRef = useRef(false);
163|  // eslint-disable-next-line react-hooks/refs -- latest-props mirror for async callbacks
164|  spoilersRef.current = spoilers;
165|  const msgsRef = useRef<ChatMessage[]>([]);
166|  // eslint-disable-next-line react-hooks/refs -- latest-props mirror for async callbacks
167|  msgsRef.current = messages;
168|  const abortRef = useRef<AbortController | null>(null);
169|
170|  // Restore the text-only conversation once, on mount.
171|  useEffect(() => {
172|    const stored = readStored(storeKey(optsRef.current.bookId));
173|    if (!stored) return;
174|    msgsRef.current = stored.messages;
175|    setMessages(stored.messages);
176|    setRemaining(stored.remaining);
177|    setSpoilers(stored.spoilers);
178|  }, []);
179|
180|  // Persist text only: never the key, never the token.
181|  useEffect(() => {
182|    try {
183|      const snap: ChatSnapshot = { messages, remaining, spoilers };
184|      window.sessionStorage.setItem(storeKey(opts.bookId), JSON.stringify(snap));
185|    } catch {
186|      // Private mode or full storage: the chat still works for the visit.
187|    }
188|  }, [messages, remaining, spoilers, opts.bookId]);
