190|  const fail = useCallback((code: string) => {
191|    abortRef.current = null;
192|    if (code === "quota" || code === "byok_required") {
193|      setByok(code);
194|      setStatus("idle");
195|    } else if (code === "human") {
196|      setNeedHuman(true);
