227|  // same tick still sends them; props alone would read the stale render.
228|  const sendHistory = useCallback(
229|    async (history: ChatMessage[], key: string | null, token: string | null) => {
230|      const o = optsRef.current;
231|      const ctrl = new AbortController();
232|      abortRef.current?.abort();
233|      abortRef.current = ctrl;
234|      setStatus("loading");
235|      setByok(null);
236|      const payload = {
237|        bookId: o.bookId,
238|        upToN: o.upToN,
239|        spoilers: spoilersRef.current,
240|        messages: history,
241|        ...(token ? { turnstileToken: token } : {}),
242|      };
243|      o.onTokenUsed?.();
244|      try {
245|        // First-byte budget only: once headers land the timer clears, so a
246|        // long healthy stream never trips it; idleness is runStream's job.
247|        const firstByte = new AbortController();
248|        const firstTimer = setTimeout(() => firstByte.abort(), CHAT_FIRST_BYTE_MS);
249|        let res: Response;
250|        try {
251|          res = await fetch("/api/chat", {
252|            method: "POST",
253|            headers: {
254|              "content-type": "application/json",
255|              ...(key ? { [BYOK_HEADER]: key } : {}),
256|            },
257|            body: JSON.stringify(payload),
258|            signal: AbortSignal.any([ctrl.signal, firstByte.signal]),
259|          });
260|        } finally {
261|          clearTimeout(firstTimer);
262|        }
263|        const contentType = res.headers.get("content-type") ?? "";
264|        if (!res.ok || !contentType.includes("text/event-stream")) {
265|          let code = "unavailable";
266|          try {
267|            code = errorCodeOf(await res.json());
268|          } catch {
269|            // No JSON error body: keep the generic code.
270|          }
271|          throw { code };
272|        }
273|        let streamed = false;
274|        let finished = false;
275|        const role: ChatRole = "assistant";
276|        await runStream(res, ctrl.signal, (event, data) => {
277|          if (event === "delta") {
278|            const text = (safeJson(data) as { text?: unknown } | null)?.text;
279|            if (typeof text !== "string" || text === "") return;
280|            streamed = true;
281|            setStatus("streaming");
282|            const next = [...msgsRef.current];
283|            const last = next[next.length - 1];
284|            if (last && last.role === role) {
285|              next[next.length - 1] = { role, content: last.content + text };
286|            } else {
287|              next.push({ role, content: text });
288|            }
289|            msgsRef.current = next;
290|            setMessages(next);
291|          } else if (event === "done") {
292|            const left = (safeJson(data) as { remaining?: unknown } | null)?.remaining;
293|            if (typeof left === "number") setRemaining(left);
294|            finished = true;
295|            setStatus("idle");
296|            abortRef.current = null;
297|          } else if (event === "error") {
298|            throw { code: errorCodeOf(safeJson(data)) };
299|          }
300|        });
301|        // A cut stream (server kill, dropped line) ends without done: show
302|        // the retry state instead of streaming forever.
303|        if ((!streamed || !finished) && !ctrl.signal.aborted) throw { code: "unavailable" };
304|      } catch (err) {
305|        // Stop stays silent; anything else (first-byte or idle timeout,
306|        // network, server error) lands here unaborted and shows its state.
307|        if (ctrl.signal.aborted) return;
308|        throw err;
309|      }
310|    },
311|    [],
312|  );
