// the stored data fails its shape check. Never throws.
export async function loadUploadedBook(
  id: string,
  deps: { kv?: KV; store?: UploadStore } = {},
): Promise<BookPayload | null> {
  if (!isUploadId(id)) return null;
  let kv = deps.kv;
