+            value={code}
+            onChange={(event) => onCode(event.target.value)}
+            autoComplete="off"
+            spellCheck={false}
+            maxLength={64}
+            placeholder="If a friend shared one with you"
+          />
+        </label>
+      ) : (
+        <button type="button" className="ob-quiet" onClick={() => setOpen(true)}>
+          Have a friend code?
+        </button>
+      )}
+    </div>
+  );
+}

